const el=(tag,text,cls)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node;};
const fmt=(value,digits=2)=>Number(value||0).toLocaleString('nl-NL',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const mod=(value,size)=>(value%size+size)%size;
function annotatedTurns(state){
 const count=state.players.length,initialStarter=mod((state.starter||0)-((state.leg||1)-1),count),visits=new Map();
 return state.history.map((turn,historyIndex)=>{let index;if(Number.isInteger(turn.player))index=turn.player;else if(state.game==='bobs27'||state.training121)index=state.players.findIndex(player=>player.name===turn.name);else{const leg=turn.leg||1,visit=visits.get(leg)||0;index=mod(initialStarter+leg-1+visit,count);visits.set(leg,visit+1);}if(index<0)index=mod(initialStarter+(turn.leg||1)-1,count);return {...turn,playerIndex:index,historyIndex};});
}
const turnsByPlayer=(state,index)=>annotatedTurns(state).filter(turn=>turn.playerIndex===index);
const gameName=state=>state.training121?'121':({x01:'X01',cricket:'Cricket',tactics:'Tactics',gotcha:'Gotcha',bobs27:"Bob's 27",fourinarow:'4 op een rij',scram:'Scram',killer:'Killer',bull41:'Bull / 41',twentyone:'21'})[state.game]||'Partij';
const time=value=>new Date(value||Date.now()).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'});
const targetLabel=target=>target===25?'Bull':String(target);

function x01Report(state){
 const players=state.players.map((player,index)=>{const turns=turnsByPlayer(state,index),darts=turns.reduce((n,t)=>n+t.darts,0),points=turns.reduce((n,t)=>n+t.score,0),firstNine=[];for(const leg of new Set(turns.map(t=>t.leg)))firstNine.push(...turns.filter(t=>t.leg===leg).slice(0,3));const firstDarts=firstNine.reduce((n,t)=>n+t.darts,0),firstPoints=firstNine.reduce((n,t)=>n+t.score,0),finishes=turns.filter(t=>t.remaining===0&&!t.bust).map(t=>t.score);return {name:player.name,stats:[['Gemiddelde',fmt(darts?points/darts*3:0)],['First nine',fmt(firstDarts?firstPoints/firstDarts*3:0)],['Hoogste beurt',String(Math.max(0,...turns.map(t=>t.score)))],['100+ / 140+ / 180',`${turns.filter(t=>t.score>=100).length} / ${turns.filter(t=>t.score>=140).length} / ${turns.filter(t=>t.score===180).length}`],['Hoogste finish',String(Math.max(0,...finishes))],['Darts totaal',String(darts)]]};});
 const rows=annotatedTurns(state).map((turn,index)=>[String(index+1),state.players[turn.playerIndex]?.name||turn.name,String(turn.score),String(turn.darts),turn.bust?'BUST':String(turn.remaining)]);
 return {title:'X01-partijoverzicht',subtitle:'Scores, gemiddelden en finishes',players,bars:[{title:'Gemiddelde per speler',items:players.map(player=>({label:player.name,value:Number(player.stats[0][1].replace(',','.')),display:player.stats[0][1]}))}],headers:['Beurt','Speler','Score','Darts','Resterend'],rows};
}

function cricketReport(state){
 const players=state.players.map((player,index)=>{const turns=turnsByPlayer(state,index),darts=turns.reduce((n,t)=>n+t.darts,0),marks=turns.reduce((n,t)=>n+(t.marks||0),0);return {name:player.name,stats:[['MPR',fmt(darts?marks/darts*3:0)],['Marks totaal',String(marks)],['Darts totaal',String(darts)],['Hoogste beurt',`${Math.max(0,...turns.map(t=>t.marks||0))} marks`]]};});
 const targetItems=state.numbers.map(target=>{let marks=0;for(const turn of state.history)for(const hit of turn.input?.hits||[])if(hit.number===target)marks+=hit.mult;return {label:targetLabel(target),value:marks,display:`${marks} marks`};});
 const rows=annotatedTurns(state).map((turn,index)=>[String(index+1),state.players[turn.playerIndex]?.name||turn.name,turn.labels||'—',String(turn.marks||0),String(turn.darts)]);
 return {title:`${gameName(state)}-partijoverzicht`,subtitle:'MPR en marks per doel',players,bars:[{title:'Marks per doel',items:targetItems},{title:'MPR per speler',items:players.map(player=>({label:player.name,value:Number(player.stats[0][1].replace(',','.')),display:player.stats[0][1]}))}],headers:['Beurt','Speler','Gegooid','Marks','Darts'],rows};
}

function bobsReport(state){
 const players=state.players.map((player,index)=>{const turns=turnsByPlayer(state,index),hits=turns.reduce((n,t)=>n+(t.hits||0),0);return {name:player.name,stats:[['Eindscore',String(player.remaining)],['Dubbels geraakt',String(hits)],['Raakpercentage',fmt(turns.length?hits/(turns.length*3)*100:0,1)+'%'],['Beste ronde',`${Math.max(0,...turns.map(t=>t.hits||0))} raak`]]};});
 const targetItems=[...Array.from({length:20},(_,i)=>i+1),25].map(target=>{const turns=state.history.filter(turn=>turn.target===target),hits=turns.reduce((n,t)=>n+(t.hits||0),0);return {label:target===25?'Bull':`D${target}`,value:turns.length?hits/(turns.length*3)*100:0,display:`${hits} raak`};});
 const rows=state.history.map(turn=>[turn.target===25?'Bull':`D${turn.target}`,turn.name,String(turn.hits||0),turn.labels||'—',String(turn.remaining)]);
 return {title:"Bob's 27-overzicht",subtitle:'Alle dubbels van sterk naar zwak',players,bars:[{title:'Raakpercentage per dubbel',items:targetItems.sort((a,b)=>b.value-a.value)}],headers:['Doel','Speler','Raak','Pijlen','Score'],rows};
}

function training121Report(state){
 const groups=[];for(const turn of annotatedTurns(state)){const attempt=turn.trainingAttempt||turn.leg||1;let group=groups.find(item=>item.attempt===attempt&&item.playerIndex===turn.playerIndex);if(!group){group={attempt,playerIndex:turn.playerIndex,name:state.players[turn.playerIndex]?.name||turn.name,turns:[]};groups.push(group);}group.turns.push(turn);}
 const levels=new Map(state.players.map((_,index)=>[index,121]));const attempts=groups.map(group=>{const darts=group.turns.reduce((n,t)=>n+t.darts,0),last=group.turns.at(-1),complete=!!last?.trainingComplete||darts>=9||(last?.remaining===0&&!last?.bust),start=group.turns[0]?.trainingStart||levels.get(group.playerIndex)||121,success=complete&&last?.remaining===0&&!last?.bust,next=last?.trainingNext||(success?start+10-darts:Math.max(121,start-1));if(complete)levels.set(group.playerIndex,next);return {...group,start,darts,complete,success,next,finish:success?last.score:0,completedAt:last?.historyIndex||0};}).filter(item=>item.complete).sort((a,b)=>a.completedAt-b.completedAt);
 const players=state.players.map((player,index)=>{const own=attempts.filter(item=>item.playerIndex===index),success=own.filter(item=>item.success);return {name:player.name,stats:[['Huidig niveau',String(levels.get(index)||121)],['Pogingen',String(own.length)],['Geslaagd',String(success.length)],['Slagingspercentage',fmt(own.length?success.length/own.length*100:0,1)+'%'],['Beste finish',String(Math.max(0,...success.map(item=>item.finish)))],['Darts totaal',String(own.reduce((n,item)=>n+item.darts,0))]]};});
 const rows=attempts.map((item,index)=>[String(index+1),item.name,String(item.start),String(item.darts),item.success?'Uit':`Niet uit`,String(item.next)]);
 return {title:'121-trainingsoverzicht',subtitle:'Niveauontwikkeling en checkouts',players,bars:[{title:'Huidig niveau',items:players.map(player=>({label:player.name,value:Number(player.stats[0][1]),display:player.stats[0][1]}))},{title:'Geslaagde pogingen',items:players.map(player=>({label:player.name,value:Number(player.stats[2][1]),display:player.stats[2][1]}))}],headers:['Poging','Speler','Niveau','Darts','Resultaat','Volgende'],rows};
}

function gotchaReport(state){
 const players=state.players.map((player,index)=>{const turns=turnsByPlayer(state,index),darts=turns.reduce((n,t)=>n+t.darts,0),points=turns.reduce((n,t)=>n+t.score,0),resets=turns.reduce((n,t)=>n+(t.resets?.length||0),0);return {name:player.name,stats:[['Eindscore',String(player.remaining)],['Gemiddelde',fmt(darts?points/darts*3:0)],['Tegenstanders op 0',String(resets)],['Hoogste beurt',String(Math.max(0,...turns.map(t=>t.score)))],['Darts totaal',String(darts)]]};});
 const rows=annotatedTurns(state).map((turn,index)=>[String(index+1),state.players[turn.playerIndex]?.name||turn.name,String(turn.score),String(turn.remaining),String(turn.resets?.length||0),turn.bust?'BUST':'Geldig']);
 return {title:'Gotcha-partijoverzicht',subtitle:'Scoreverloop en geraakte tegenstanders',players,bars:[{title:'Eindscore per speler',items:players.map(player=>({label:player.name,value:Number(player.stats[0][1]),display:player.stats[0][1]}))},{title:'Tegenstanders op 0 gezet',items:players.map(player=>({label:player.name,value:Number(player.stats[2][1]),display:player.stats[2][1]}))}],headers:['Beurt','Speler','Score','Totaal','Resets','Status'],rows};
}

function fourInRowReport(state){
 const players=state.players.map((player,index)=>{const turns=turnsByPlayer(state,index),cells=state.fourOwners.filter(owner=>owner===index).length,darts=turns.reduce((sum,turn)=>sum+(turn.darts||0),0),claims=turns.reduce((sum,turn)=>sum+(turn.captured?.length||0),0);return {name:`${player.fourSymbol||''} ${player.name}`.trim(),stats:[['Vakken veroverd',String(cells)],['Claims',String(claims)],['Darts totaal',String(darts)],['Punten geraakt',String(turns.reduce((sum,turn)=>sum+(turn.score||0),0))]]};});
 const rows=annotatedTurns(state).map((turn,index)=>[String(index+1),state.players[turn.playerIndex]?.name||turn.name,turn.labels||'—',String(turn.darts||0),String(turn.captured?.length||0)]);
 return {title:'4-op-een-rij-overzicht',subtitle:'Veroverde vakken en alle gespeelde beurten',players,bars:[{title:'Vakken per speler',items:players.map((player,index)=>({label:player.name,value:state.fourOwners.filter(owner=>owner===index).length,display:`${state.fourOwners.filter(owner=>owner===index).length} vakken`}))}],headers:['Beurt','Speler','Gegooid','Darts','Vakken'],rows};
}

function sonnyReport(state){
 const players=state.players.map((player,index)=>{const turns=turnsByPlayer(state,index),darts=turns.reduce((sum,turn)=>sum+(turn.darts||0),0);let stats;
  if(state.game==='scram')stats=[['Eindscore',String(player.scramScore||0)],['Darts totaal',String(darts)],['Hoogste beurt',String(Math.max(0,...turns.map(turn=>turn.score||0)))]];
  else if(state.game==='killer')stats=[['Eigen getal',String(player.killerNumber??'—')],['KILLER-letters',String(player.killerLetters||0)],['Status',player.killerEliminated?'Uitgeschakeld':index===state.winner?'Winnaar':'Actief'],['Darts totaal',String(darts)]];
  else if(state.game==='bull41')stats=[['Eindscore',String(player.bull41Score||0)],['Darts totaal',String(darts)],['Hoogste scorebeurt',String(Math.max(0,...turns.map(turn=>turn.score||0)))]];
  else stats=[['Resultaat',player.twentyOneAdjusted===null?'Niet voltooid':`${player.twentyOneAdjusted} pijlen`],['Triples',String(player.twentyOneTriples||0)],['Darts totaal',String(darts)]];
  return {name:player.name,stats};});
 const value=player=>state.game==='scram'?player.scramScore||0:state.game==='killer'?player.killerLetters||0:state.game==='bull41'?player.bull41Score||0:player.twentyOneAdjusted||0;
 const rows=annotatedTurns(state).map((turn,index)=>[String(index+1),state.players[turn.playerIndex]?.name||turn.name,turn.role||'Beurt',turn.labels||'—',String(turn.score||0),String(turn.darts||0)]);
 return {title:`${gameName(state)}-overzicht`,subtitle:'Resultaat en alle gespeelde beurten',players,bars:[{title:'Resultaat per speler',items:players.map((player,index)=>({label:player.name,value:value(state.players[index]),display:player.stats[0][1]}))}],headers:['Beurt','Speler','Rol','Gegooid','Score','Darts'],rows};
}

export function buildGameReport(state){
 const report=state.training121?training121Report(state):state.game==='bobs27'?bobsReport(state):state.game==='gotcha'?gotchaReport(state):state.game==='fourinarow'?fourInRowReport(state):['scram','killer','bull41','twentyone'].includes(state.game)?sonnyReport(state):['cricket','tactics'].includes(state.game)?cricketReport(state):x01Report(state);
 return {...report,started:time(state.startedAt),ended:time(state.completedAt||Date.now()),totalDarts:state.history.reduce((n,turn)=>n+(turn.darts||0),0),game:gameName(state)};
}

export function renderGameReport(state,dialog){
 dialog.querySelector('#game-report')?.remove();dialog.querySelector('#match-summary')?.remove();const report=buildGameReport(state),section=el('section',undefined,'game-report');section.id='game-report';section.append(el('h3',report.title),el('p',report.subtitle,'game-report-subtitle'));
 const meta=el('dl',undefined,'game-report-meta');for(const [label,value] of [['Begintijd',report.started],['Eindtijd',report.ended],['Darts totaal',String(report.totalDarts)]]){meta.append(el('dt',label),el('dd',value));}section.append(meta);
 const cards=el('div',undefined,'game-report-players');for(const player of report.players){const card=el('article');card.append(el('h4',player.name));const stats=el('dl');for(const [label,value] of player.stats){stats.append(el('dt',label),el('dd',value));}card.append(stats);cards.append(card);}section.append(cards);
 for(const chart of report.bars){const block=el('div',undefined,'game-report-chart');block.append(el('h4',chart.title));const maximum=Math.max(1,...chart.items.map(item=>item.value));for(const item of chart.items){const row=el('div');row.append(el('span',item.label));const meter=el('i'),fill=el('b');fill.style.width=`${Math.max(item.value?4:0,item.value/maximum*100)}%`;meter.append(fill);row.append(meter,el('strong',item.display));block.append(row);}section.append(block);}
 const wrap=el('div',undefined,'game-report-table-wrap'),table=el('table',undefined,'game-report-table'),head=table.createTHead(),heading=head.insertRow();for(const label of report.headers)heading.append(el('th',label));const body=table.createTBody();for(const values of report.rows){const row=body.insertRow();for(const value of values)row.append(el('td',value));}wrap.append(table);section.append(wrap);
 const share=el('button','Delen als afbeeldingen','game-report-share primary wide');share.type='button';share.onclick=async()=>{const original=share.textContent;share.disabled=true;share.textContent='Afbeeldingen maken...';try{await shareGameReport(state);share.textContent='Deelmenu geopend';}catch(error){share.textContent=error?.message||'Delen is niet gelukt';}finally{setTimeout(()=>{share.disabled=false;share.textContent=original;},2200);}};section.append(share);dialog.querySelector('#result-title').after(section);
}

const rounded=(context,x,y,width,height,radius=18)=>{context.beginPath();context.roundRect(x,y,width,height,radius);context.fill();};
const wrapText=(context,text,width)=>{const words=String(text).split(/\s+/),lines=[];let line='';for(const word of words){const next=line?line+' '+word:word;if(context.measureText(next).width<=width||!line)line=next;else{lines.push(line);line=word;}}if(line)lines.push(line);return lines;};
function overviewCanvas(report){
 const width=1080,margin=56,inner=width-margin*2,playerHeight=report.players.reduce((sum,player)=>sum+82+Math.ceil(player.stats.length/2)*54,0),chartsHeight=report.bars.reduce((sum,chart)=>sum+75+chart.items.length*42,0),height=300+playerHeight+chartsHeight,canvas=document.createElement('canvas'),context=canvas.getContext('2d');canvas.width=width;canvas.height=height;context.textBaseline='middle';context.fillStyle='#0c151b';context.fillRect(0,0,width,height);let y=55;
 context.fillStyle='#c8f56a';context.font='800 47px sans-serif';context.fillText(report.title,margin,y+25);y+=72;context.fillStyle='#93a9b2';context.font='22px sans-serif';context.fillText(`${report.started} – ${report.ended}  ·  ${report.totalDarts} darts`,margin,y+20);y+=60;
 for(const player of report.players){const rows=Math.ceil(player.stats.length/2),h=70+rows*54;context.fillStyle='#142129';rounded(context,margin,y,inner,h);context.fillStyle='#83d9ef';context.font='800 29px sans-serif';context.fillText(player.name,margin+25,y+34);player.stats.forEach(([label,value],index)=>{const column=index%2,row=Math.floor(index/2),x=margin+25+column*(inner/2),lineY=y+84+row*54;context.fillStyle='#93a9b2';context.font='700 16px sans-serif';context.fillText(label.toUpperCase(),x,lineY-13);context.fillStyle='#fff';context.font='800 25px sans-serif';context.fillText(value,x,lineY+13);});y+=h+18;}
 for(const chart of report.bars){const h=58+chart.items.length*42;context.fillStyle='#142129';rounded(context,margin,y,inner,h);context.fillStyle='#83d9ef';context.font='800 23px sans-serif';context.fillText(chart.title.toUpperCase(),margin+24,y+28);const maximum=Math.max(1,...chart.items.map(item=>item.value));chart.items.forEach((item,index)=>{const lineY=y+67+index*42;context.fillStyle='#fff';context.font='20px sans-serif';context.fillText(item.label,margin+24,lineY);context.fillStyle='#20313b';rounded(context,margin+210,lineY-8,inner-350,17,8);context.fillStyle='#c8f56a';rounded(context,margin+210,lineY-8,(inner-350)*item.value/maximum,17,8);context.fillStyle='#fff';context.font='700 19px sans-serif';context.fillText(item.display,margin+inner-110,lineY);});y+=h+18;}
 context.fillStyle='#728b96';context.font='18px sans-serif';context.fillText('Gemaakt met 180 Hitters',margin,height-24);return canvas;
}
function detailCanvas(report,rows,page,pageCount){
 const width=1080,margin=44,inner=width-margin*2,columns=report.headers.length,colWidth=inner/columns,canvas=document.createElement('canvas'),context=canvas.getContext('2d');context.font='20px sans-serif';const prepared=rows.map(values=>{const cells=values.map(value=>wrapText(context,value,colWidth-20));return {cells,height:Math.max(56,Math.max(...cells.map(lines=>lines.length))*27+18)};}),height=220+prepared.reduce((sum,row)=>sum+row.height,0);canvas.width=width;canvas.height=height;context.textBaseline='middle';context.fillStyle='#0c151b';context.fillRect(0,0,width,height);context.fillStyle='#c8f56a';context.font='800 41px sans-serif';context.fillText(report.title,margin,58);context.fillStyle='#93a9b2';context.font='700 20px sans-serif';context.fillText(`DETAILS · DEEL ${page} VAN ${pageCount}`,margin,105);let y=140,x=margin;context.fillStyle='#20313b';rounded(context,margin,y,inner,56,10);context.fillStyle='#c8f56a';context.font='800 17px sans-serif';report.headers.forEach(label=>{context.fillText(label.toUpperCase(),x+10,y+28);x+=colWidth;});y+=56;context.font='20px sans-serif';prepared.forEach((row,index)=>{context.fillStyle=index%2?'#10202a':'#142731';context.fillRect(margin,y,inner,row.height-2);x=margin;row.cells.forEach(lines=>{context.fillStyle='#fff';let lineY=y+18;for(const line of lines){context.fillText(line,x+10,lineY);lineY+=27;}x+=colWidth;});y+=row.height;});return canvas;
}
export function createGameReportImages(state){const report=buildGameReport(state),pageSize=14,pageCount=Math.max(1,Math.ceil(report.rows.length/pageSize)),images=[{canvas:overviewCanvas(report),suffix:'overzicht'}];for(let page=0;page<pageCount;page++)images.push({canvas:detailCanvas(report,report.rows.slice(page*pageSize,(page+1)*pageSize),page+1,pageCount),suffix:`details-${String(page+1).padStart(2,'0')}`});return {report,images};}

export async function shareGameReport(state){
 const {report,images}=createGameReportImages(state),bridge=window.DartsAndroid,date=new Date().toISOString().slice(0,10),prefix=report.game.toLowerCase().replace(/[^a-z0-9]+/g,'-');const parts=images.map(({canvas,suffix})=>{const data=canvas.toDataURL('image/png');if(!data.startsWith('data:image/png;base64,'))throw Error('Afbeelding kon niet worden gemaakt.');return {canvas,filename:`180-hitters-${prefix}-${date}-${suffix}.png`,encoded:data.slice(data.indexOf(',')+1)};});
 const append=async encoded=>{for(let offset=0,index=0;offset<encoded.length;offset+=196608,index++){if(!bridge.appendPngShare(encoded.slice(offset,offset+196608)))throw Error('Afbeelding kon niet worden overgedragen.');if(index%8===7)await new Promise(resolve=>setTimeout(resolve,0));}};
 if(bridge?.beginPngShareCollection&&bridge?.beginPngSharePart&&bridge?.appendPngShare&&bridge?.finishPngSharePart&&bridge?.finishPngShareCollection){if(!bridge.beginPngShareCollection())throw Error('Delen kon niet worden voorbereid.');for(const part of parts){if(!bridge.beginPngSharePart(part.filename))throw Error('Afbeelding kon niet worden voorbereid.');await append(part.encoded);if(!bridge.finishPngSharePart())throw Error('Afbeelding kon niet worden opgeslagen.');}if(!bridge.finishPngShareCollection())throw Error('Android kon het deelmenu niet openen.');return;}
 const files=[];for(const part of parts){const blob=await new Promise(resolve=>part.canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Afbeelding kon niet worden gemaakt.');files.push(new File([blob],part.filename,{type:'image/png'}));}if(navigator.share&&(!navigator.canShare||navigator.canShare({files}))){await navigator.share({title:report.title,text:`Mijn ${report.game}-resultaat`,files});return;}for(const file of files){const link=document.createElement('a');link.href=URL.createObjectURL(file);link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1500);}
}
